select wod.*, wo.id woId, wo.serial_number sn, wo.applicant_name founderName, wo.reviewer_name reviewerName, wo.create_time createTime, wo.review_time reviewTime, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, batch.name areaBatchName, mbf.id mbfId, mbf.name mbfName, wwork.id wworkId, wwork.name wworkName, wm.measure_unit wmu, wm.measure_precision wmp, wm.accounting_unit wau, wm.accounting_precision wap, ww.id wwId, ww.name wwName, su.name sname, spo.serial_number spoNumber, u.name uName, war.start_time warStartTime, wo.bool_scheduling boolScheduling, wo.outbound_type_selection woType, wo.child_order_number childOrderNumber from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id left join wms_measure wm on wm.classification_id = wod.classify_id left join contract_project p on p.id = wod.project_id left join mes_building_workshop mbf on wod.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wod.warehouse_id left join sys_user su on su.id = wod.recipient_id left join plan_monomer pm on pm.id = wod.monomer_id left join plan_area pa on pa.id = wod.area_id left join wms_for_sale_detail wfsd on wfsd.outbound_detail_id = wod.id and wfsd.bool_delete_enum = 0 and exists (select 1 from wms_for_sale sale_parent where sale_parent.serial_number = wfsd.for_sale_serial_number and sale_parent.outbound_id = wod.outbound_id and sale_parent.bool_delete_enum = 0) left join scm_purchase_order spo on spo.id = wod.purchase_id left join sys_user u on u.id = wo.applicant_id left join wms_approve_record war on war.id = wo.approve_record_id left join wms_workshop wwork on wod.source_workshop_id = wwork.id left join plan_area_batch batch on batch.id = wod.area_batch_id and batch.bool_delete_enum = 0 where wod.bool_delete_enum = 0 AND wo.review_status = 2
and wod.id in
#{id}
and wod.basic_class = #{basicClass}
and wod.bool_party_a = 1
and wod.bool_party_a = 0
and wod.material_is_whole = #{materialIsWhole}
AND wod.warehouse_id = #{warehouseId}
AND wo.review_status = #{outReviewStatus}
AND wod.recipient_id = #{recipientId}
