select wod.*, wod.outbound_time outboundTime, wm.*, wo.serial_number woSN, p.serial_number projectNumber, wo.review_time reviewTime, p.name pn, pm.name pmName, pa.name paName, pm2.name pm2Name, pa2.name pa2Name, p2.name p2n, p2.serial_number directionProjectSerialNumber, u.name recipientName, u.id recipientId, mbw.name workshopName, batch.name areaBatchName, wwork.name wworkName, wc.name classifyName, ww.name warehouseName, sbc.name branchCompanyName, wo.applicant_name applicantName from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id left join contract_project p on p.id = wod.project_id left join contract_project p2 on p2.id = wod.source_project_id left join wms_classification wc on wod.classify_id = wc.id left join wms_measure wm on wm.classification_id = wod.classify_id left join plan_monomer pm on pm.id = wod.monomer_id left join plan_area pa on pa.id = wod.area_id left join plan_monomer pm2 on pm2.id = wod.source_monomer_id left join plan_area pa2 on pa2.id = wod.source_area_id left join sys_user u on u.id = wod.recipient_id and u.bool_delete_enum = 0 left join mes_building_workshop mbw on mbw.id = wod.workshop_id left join wms_warehouse ww on ww.id = wod.warehouse_id left join wms_for_sale_detail wfsd on wfsd.outbound_detail_id = wod.id and wfsd.bool_delete_enum = 0 and exists (select 1 from wms_for_sale sale_parent where sale_parent.serial_number = wfsd.for_sale_serial_number and sale_parent.outbound_id = wod.outbound_id and sale_parent.bool_delete_enum = 0) left join wms_workshop wwork on wod.source_workshop_id = wwork.id left join sys_branch_company sbc on sbc.id = wfsd.branch_company_id left join plan_area_batch batch on batch.id = wod.area_batch_id and batch.bool_delete_enum = 0 where wod.bool_delete_enum = 0 and wo.review_status = 2
