            or su.name like CONCAT('%', #{operatorName},'%'))
        
        
            and wod.classify_id in
            
                #{item}
            
        



        
            and wod.project_id is null
        
        
            and wod.project_id IS NOT NULL
        
        
            AND wod.project_id = #{projectId}
        
        
            and wod.workshop_id = #{workshopId}
        
        
            and wod.monomer_id = #{monomerId}
        
        
            and wod.area_id = #{areaId}
        
        
            and wod.width = #{width}
        
        
            and wod.length = #{length}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and wod.quantity >= #{minLength}
        
        
            and wod.quantity <= #{maxLength}
        
        
            and wod.theory_thickness = #{theoryThickness}
        
        
            and wod.thickness = #{thickness}
        
        
            and wod.color like CONCAT('%', #{color},'%')
        
        
            and wod.specification like CONCAT('%', #{specification},'%')
        
        
            and wod.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND wod.brand like CONCAT('%',#{brand},'%')
        
        
            and wo.factory_id = #{factoryId}
        
        
            and wod.source_workshop_id in
            
                #{item}

select wod.project_id projectId, wod.basic_class basicClass, SUM( wod.mete ) mete, SUM( wod.amount ) amount, SUM( wod.amount_excluding_vat ) amount_excluding_vat, DATE_FORMAT(wo.review_time, '%Y-%m') time from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id and wo.bool_delete_enum = 0 where wod.bool_delete_enum = 0
and wo.review_status = #{reviewStatus}
and wod.basic_class in
#{basicClass}
and
DATE_FORMAT(wo.review_time, '%Y-%m') = #{yearMonthStr}
and wod.project_id in
#{projectId}
and wod.project_id is null
and wod.classify_id not in
#{classifyId}
and wod.classify_id in
#{classifyId}
group by wod.project_id,wod.basic_class,DATE_FORMAT(wo.review_time, '%Y-%m')

select DATE_FORMAT(wo.review_time, '%Y-%m') as yearMonth, '出库' as type, wc.id as classifyId, wc.basic_class as basicClass, wc.name as classifyName, wod.length as length, wod.width as width, wod.thickness as thickness, wod.specification as specification, wod.brand as brand, wm.measure_unit as measureUnit, SUM(wod.quantity) as quantityCount, wm.accounting_unit as accountingUnit, SUM(wod.mete) as meteCount, SUM( wod.unit_price ) / count(1) AS unitPrice, SUM( wod.unit_price_excluding_vat ) / count(1) AS unitPriceExcludingVAT, SUM( wod.amount ) as amountCount, SUM( wod.amount_excluding_VAT ) as amountExcludingVatCount, wo.serial_number as serialNumber, mbw.id as workshopId, mbw.name workshopName from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id and wo.bool_delete_enum = 0 left join wms_measure wm on wm.classification_id = wod.classify_id left join mes_building_workshop mbw on mbw.id = wod.workshop_id left join wms_classification wc on wod.classify_id = wc.id where wod.bool_delete_enum = 0
and wo.review_status = #{reviewStatus}
and wod.basic_class in
#{basicClass}
and wod.project_id = #{projectId}
and wod.project_id is null
and
DATE_FORMAT(wo.review_time, '%Y-%m') = #{yearMonthStr}
and wod.classify_id not in
#{classifyId}
and wod.classify_id in
#{classifyId}
group by DATE_FORMAT(wo.review_time, '%Y-%m'), wc.basic_class, wc.id, wod.specification, wod.length, wod.width, wod.thickness, wm.measure_unit, wod.brand, wm.accounting_unit, wo.serial_number, wm.measure_unit, mbw.id

select wod.* from wms_move_outbound_detail wod left join wms_outbound wo on wod.outbound_id = wo.id where wod.bool_delete_enum = 0 and wod.project_id is not null and wo.outbound_type_selection in (1,128) and wod.basic_class in (1,2,4,256) and wo.review_status = 2
and DATE_FORMAT(wo.review_time, '%Y') = #{time}
and wod.workshop_id = #{workshopId}
and DATE_FORMAT(wo.review_time, '%Y-%m') = #{timeOne}

        select receive_id,receive_detail_id,amount,amount_excluding_vat from wms_move_outbound_detail where  bool_delete_enum=0
        
            and receive_id = #{receiveId}
        
        
            and receive_detail_id in
            
                #{item}

select wod.*, case when wod.basic_class = 1 then wod.actual_theory_weight else wod.mete end as actual_theory_weight, wc.id classifyId, wc.name classifyName, su.name recipientName from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id left join wms_classification wc on wc.id = wod.classify_id left join sys_user su on su.id = wod.recipient_id where wod.bool_delete_enum = 0 and wo.review_status = 2 and wo.outbound_type_selection in (1,128)
and wod.basic_class = #{basicClass}
and wod.thickness = #{thickness}
and wod.specification = #{material}
and (wod.specification = #{specification} or wod.specification = #{prefixSpecification})
and wod.basic_class in (1,2)
and wod.project_id = #{projectId}
and wod.workshop_id = #{workShopId}

select wod.basic_class basicClass, wod.thickness thickness, wod.specification specification, sum(wod.actual_theory_weight) as actual_theory_weight, sum(wod.mete) meteCount from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id where wod.bool_delete_enum = 0 and wo.review_status = 2 and wo.outbound_type_selection in (1,128) and wod.basic_class = 1
and wod.project_id = #{projectId}
and wod.workshop_id = #{workShopId}
group by wod.basic_class,wod.thickness,wod.specification

select wod.basic_class basicClass, wod.specification specification, sum(wod.mete) meteCount from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id where wod.bool_delete_enum = 0 and wo.review_status = 2 and wo.outbound_type_selection in (1,128) and wod.basic_class = 2
and wod.project_id = #{projectId}
and wod.workshop_id = #{workShopId}
group by wod.basic_class,wod.specification

SELECT 1 AS lossWorkProgressStatisticsEnum, ym_t.`year_month`, IFNULL(ROUND(wmod_t.productMonthOutput,3),0) AS productMonthOutput FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year_month`
) ym_t LEFT JOIN ( SELECT DATE_FORMAT( wmod.create_time, '%Y-%m' ) AS `year_month`, IFNULL(SUM( wmod.mete ), 0 ) / 1000000 AS productMonthOutput FROM wms_move_outbound_detail wmod LEFT JOIN wms_outbound wo ON wmod.outbound_id = wo.id AND wo.bool_delete_enum = 0 WHERE wmod.bool_delete_enum = 0 AND wo.review_status = 2 AND wo.outbound_type_selection = 1 AND wmod.basic_class & 263 > 0
and wmod.project_id = #{projectId}
and wmod.workshop_id = #{workShopId}
AND date_format(wmod.create_time, '%Y-%m') >= #{minYearMonth}
AND date_format(wmod.create_time, '%Y-%m') <= #{maxYearMonth}
GROUP BY DATE_FORMAT( wmod.create_time, '%Y-%m' ) ) wmod_t ON ym_t.`year_month` = wmod_t.`year_month`

SELECT wod.*, wo.id woId, wo.serial_number sn, wo.applicant_name founderName, wo.reviewer_name reviewerName, wo.create_time createTime, wo.review_time reviewTime, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, wwork.id wworkId, wwork.name wworkName, wm.measure_unit wmu, wm.measure_precision wmp, wm.accounting_unit wau, wm.accounting_precision wap, ww.id wwId, ww.name wwName, su.name sname, spo.serial_number spoNumber, u.name uName, war.start_time warStartTime, wo.bool_scheduling boolScheduling, wo.outbound_type_selection woType from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id left join wms_measure wm on wm.classification_id = wod.classify_id left join contract_project p on p.id = wod.project_id left join mes_building_workshop mbf on wod.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wod.warehouse_id left join sys_user su on su.id = wod.recipient_id left join plan_monomer pm on pm.id = wod.monomer_id left join plan_area pa on pa.id = wod.area_id left join wms_for_sale_detail wfsd on wfsd.outbound_detail_id = wod.id and wfsd.bool_delete_enum = 0 and exists (select 1 from wms_for_sale sale_parent where sale_parent.serial_number = wfsd.for_sale_serial_number and sale_parent.outbound_id = wod.outbound_id and sale_parent.bool_delete_enum = 0) left join scm_purchase_order spo on spo.id = wod.purchase_id left join sys_user u on u.id = wo.applicant_id left join wms_approve_record war on war.id = wo.approve_record_id left join wms_workshop wwork on wod.source_workshop_id = wwork.id LEFT JOIN wms_classification wcf ON wod.classify_id = wcf.id WHERE wod.bool_delete_enum = 0 AND wo.review_status = 2 AND wo.outbound_type_selection = 1 AND wod.basic_class & 263 > 0
and wod.basic_class = #{basicClass}
and wod.project_id = #{projectId}
and wod.workshop_id = #{workShopId}
AND date_format(wod.create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(wod.create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
and wcf.name like CONCAT('%', #{classifyName},'%')

SELECT wmod.* FROM wms_move_outbound_detail wmod INNER JOIN wms_outbound wo ON wmod.outbound_id = wo.id WHERE wmod.bool_delete_enum = 0 AND wo.bool_delete_enum = 0 AND wo.review_status = 2
AND wmod.basic_class & #{basicClass} > 0
and wmod.classify_id in
#{item}
AND DATE_FORMAT(wmod.create_time, "%Y") = DATE_FORMAT(#{yearDate}, "%Y")
AND DATE_FORMAT(wmod.create_time, "%Y-%m") = DATE_FORMAT(#{mouthDate}, "%Y-%m")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = wmod.project_id )
AND wmod.workshop_id = #{workshopId}
AND wmod.project_id = #{projectId}
order by wmod.create_time desc

SELECT DATE_FORMAT( wmod.create_time, '%Y-%m' ) AS `year_month`, IFNULL(SUM( wmod.mete ), 0 ) / 1000 AS productMonthOutput FROM wms_move_outbound_detail wmod LEFT JOIN wms_outbound wo ON wmod.outbound_id = wo.id AND wo.bool_delete_enum = 0 WHERE wmod.bool_delete_enum = 0 AND wo.review_status = 2 AND wo.outbound_type_selection = 1 AND wmod.basic_class & 263 > 0
and wmod.project_id = #{projectId}
GROUP BY DATE_FORMAT( wmod.create_time, '%Y-%m' )

SELECT y_t.`year` as `dateTime`, (IFNULL(temp1.mete, 0) - IFNULL(temp2.mete, 0)) as mete FROM (
select DATE_FORMAT(#{i}, '%Y') as `year`
) y_t LEFT JOIN ( SELECT DATE_FORMAT(wmod.create_time, "%Y") as dateTime, IFNULL( SUM( wmod.mete ), 0 ) mete FROM wms_move_outbound_detail wmod INNER JOIN wms_outbound wo ON wmod.outbound_id = wo.id WHERE wmod.bool_delete_enum = 0 AND wo.bool_delete_enum = 0 AND wo.review_status = 2 and wo.outbound_type_selection = 1 AND wmod.basic_class & 263 > 0
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = wmod.project_id )
AND wmod.workshop_id = #{workshopId}
group by DATE_FORMAT(wmod.create_time, "%Y") ) AS temp1 ON temp1.dateTime = y_t.`year` LEFT JOIN ( SELECT DATE_FORMAT(wrd.create_time, "%Y") as dateTime, IFNULL( SUM( wrd.mete ), 0 ) mete FROM wms_return_detail AS wrd INNER JOIN wms_return AS wr ON wrd.return_id = wr.id LEFT JOIN wms_material_returnable wmr ON wrd.material_returnable_id = wmr.id AND wmr.bool_delete_enum = 0 WHERE wrd.bool_delete_enum = 0 AND wr.bool_delete_enum = 0 AND wr.review_status = 2 AND wrd.basic_class & 263 > 0
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = wrd.project_id )
AND wmr.workshop_id = #{workshopId}
and wr.outbound_type_selection = 1 group by DATE_FORMAT(wrd.create_time, "%Y" ) ) temp2 ON temp2.dateTime = y_t.`year`

select wod.*, wo.id woId, wo.serial_number sn, wo.applicant_name founderName, wo.reviewer_name reviewerName, wo.create_time createTime, wo.review_time reviewTime, wo.bool_scheduling boolScheduling, wo.outbound_type_selection woType, wo.child_order_number childOrderNumber from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id and wo.bool_delete_enum = 0 where wod.bool_delete_enum = 0 and wod.bool_party_a = 0 and wo.review_status = 2
and wod.source_workshop_id = #{sourceWorkshopId}
and wod.basic_class & #{basicClass} > 0
AND date_format(wo.review_time, '%Y-%m-%d') >= date_format(#{outboundTime[0]}, '%Y-%m-%d')
AND date_format(wo.review_time, '%Y-%m-%d') <= date_format(#{outboundTime[1]}, '%Y-%m-%d')
and wod.permission_factory_id = #{factoryId}

select wod.*, wo.review_time reviewTime from wms_move_outbound_detail wod left join wms_outbound wo on wo.id = wod.outbound_id and wo.bool_delete_enum = 0 and wo.review_status = 2 where wod.bool_delete_enum = 0 and wod.bool_party_a = 0
and wod.source_workshop_id = #{workshopId}
and wo.review_time >= #{startDay}
and wo.review_time <= #{endDay}
and wod.project_id in
#{item}
and wod.basic_class & #{basicClass} > 0
